contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with parameters controlling calls
    function run(address target, bytes calldata data, uint sendAmt, bool callWithdraw, bool callCommand) public payable {
        require(address(this).balance >= sendAmt);

        // read initial observable state
        address ownerBefore = c.Owner();
        uint balBefore = address(c).balance;

        // perform calls depending on flags
        bool withdrawReverted = false;
        if (callWithdraw) {
            try c.withdraw{value: 0}() {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }
        }

        bool commandReverted = false;
        if (callCommand) {
            // send sendAmt as value to Command
            try c.Command{value: sendAmt}(target, data) {
                commandReverted = false;
            } catch {
                commandReverted = true;
            }
        }

        uint balAfter = address(c).balance;
        address ownerAfter = c.Owner();

        // General rule: if caller (this contract) is not Owner, then any attempted withdraw or Command call must either revert
        // or leave the contract balance unchanged; also Owner must never change as a result of these calls.
        bool isOwner = (ownerBefore == address(this));

        // Build assertion: owner invariant and non-owner cannot decrease balance by successful call
        assert(ownerAfter == ownerBefore && (isOwner || (balAfter == balBefore) || (withdrawReverted && commandReverted)));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with parameters controlling calls
    function run(uint depositToC, bool callWithdraw) public payable {
        // ensure we can fund this contract to forward value if requested
        require(address(this).balance >= depositToC);

        // initial observations
        address ownerBefore = c.Owner();
        uint balBefore = address(c).balance;

        // optionally fund C by sending Ether to it via the test contract's fallback (receive)
        if (depositToC > 0) {
            // send Ether directly to C's receive()
            (bool sent,) = address(c).call{value: depositToC}("");
            // ignore send success here; it's allowed to fail if receive reverts, but that's part of behavior
        }

        // perform withdraw and capture whether it reverted
        bool withdrawReverted;
        try c.withdraw{value: 0}() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // observations after the attempt
        address ownerAfter = c.Owner();
        uint balAfter = address(c).balance;

        // General rule asserted:
        // 1) Owner never changes.
        // 2) If withdraw succeeded, then C's balance after is either zero and decreased by exactly balBefore+depositToC (i.e., emptied),
        //    and cannot be a positive smaller value. If withdraw reverted, balance must be unchanged from after any deposit.
        // Note: since deposit may have failed, we compare relative to balBefore and balAfter.
        if (withdrawReverted) {
            // if reverted, balance unchanged compared to what it was after deposits (which is balBefore or balBefore+deposit)
            assert(ownerAfter == ownerBefore && balAfter >= balBefore);
        } else {
            // if succeeded, owner unchanged and contract should have been emptied (balance == 0)
            assert(ownerAfter == ownerBefore && balAfter == 0);
        }
    }

    receive() external payable {}
}

