contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function driving c
    function run(address payable target, uint amount) public payable {
        require(address(this).balance >= amount);

        // observe before-values
        address owner_before = c.Owner();
        uint balance_before = address(c).balance;

        // call multiplicate sending `amount` wei
        bool reverted;
        try c.multiplicate{value: amount}(target) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        address owner_after = c.Owner();
        uint balance_after = address(c).balance;

        // General rule asserted:
        // 1) Owner must not change as a result of multiplicate.
        // 2) The contract's balance after the call can never exceed the prior balance plus the sent amount.
        //    (i.e., multiplicate cannot create ether out of thin air)
        // 3) If the call did not revert and balance decreased, the decrease is at most balance_before + amount
        //    (this follows from 2 but makes the resource movement explicit)
        assert(
            owner_before == owner_after
            && balance_after <= balance_before + amount
            && (reverted || balance_before >= balance_after || balance_after <= balance_before + amount)
        );
    }

    // allow receiving Ether so this contract can fund calls
    receive() external payable {}
}

