contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test behavior of multiplicate with arbitrary adr and sent amount.
    // msg.sender for calls to c is this contract.
    function run(address adr, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // read balance before
        uint256 before = address(c).balance;

        // call multiplicate and capture whether it reverted
        bool reverted;
        try c.multiplicate{value: amount}(adr) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = address(c).balance;

        // General rule asserted:
        // If this contract is NOT the Owner then multiplicate must not increase c's balance.
        // We observe Owner via c.Owner() getter. This assert states that when msg.sender (this)
        // is not Owner, the balance after is <= balance before (i.e., not increased).
        // When this contract is Owner, no restriction here (the function may transfer out funds
        // which could decrease the balance, but should not be required to increase it).
        bool amOwner = (c.Owner() == address(this));

        assert(amOwner || (after <= before));
    }

    receive() external payable {}
}

